"""Built-in per-route widget HTML generated by Python (no npm/React build).

This module is the route dispatcher. The templates live in route_templates_generic,
route_templates_pizza and route_templates_flight and are re-exported here, so existing
imports keep working.
"""

from __future__ import annotations

from typing import Any, Callable, Dict, Optional

from nitrostack.widgets.host_bridge import wrap_widget_page  # noqa: F401
from nitrostack.widgets.views import missing_body, render_body  # noqa: F401
from nitrostack.widgets.route_templates_generic import (  # noqa: F401
    _generic_render_js,
    _CALC_CSS,
    _CARD_CSS,
    _TABLE_CSS,
    _CHART_CSS,
    _GENERIC_CSS,
    _MISSING_CSS,
    _CALC_JS,
    _CARD_JS,
    _TABLE_JS,
    _CHART_JS,
    _page,
    build_generic_widget,
    build_missing_widget,
    build_calculator_result_widget,
    build_card_widget,
    build_table_widget,
    build_chart_widget,
)
from nitrostack.widgets.route_templates_pizza import (  # noqa: F401
    _PIZZA_LIST_CSS,
    _PIZZA_MAP_CSS,
    _PIZZA_SHOP_CSS,
    _PIZZA_LIST_JS,
    _MAPBOX_HEAD,
    _pizza_map_js,
    _PIZZA_SHOP_JS,
    build_pizza_list_widget,
    build_pizza_map_widget,
    build_pizza_shop_widget,
)
from nitrostack.widgets.route_templates_flight import (  # noqa: F401
    _FLIGHT_CSS,
    _FLIGHT_SEARCH_JS,
    _AIRPORT_JS,
    _place_code_js,
    _FLIGHT_DETAILS_JS,
    _ORDER_SUMMARY_JS,
    _SEAT_JS,
    _CANCEL_JS,
    build_flight_search_results_widget,
    build_flight_details_widget,
    build_airport_search_widget,
    build_order_summary_widget,
    build_seat_selection_widget,
    build_order_cancellation_widget,
)


_ROUTE_BUILDERS: Dict[str, Callable[[Any | None], str]] = {
    "pizza-list": build_pizza_list_widget,
    "pizza-map": build_pizza_map_widget,
    "pizza-shop": build_pizza_shop_widget,
    "calculator-result": build_calculator_result_widget,
    "card": build_card_widget,
    "table": build_table_widget,
    "chart": build_chart_widget,
    "flight-search-results": build_flight_search_results_widget,
    "flight-details": build_flight_details_widget,
    "airport-search": build_airport_search_widget,
    "order-summary": build_order_summary_widget,
    "seat-selection": build_seat_selection_widget,
    "order-cancellation": build_order_cancellation_widget,
}


def _route_id(route: str) -> str:
    return (route or "").strip().strip("/").removeprefix("widget/").removesuffix(".html")


def render_widget_html(route: str, data: Any | None = None) -> Optional[str]:
    """Python-rendered HTML for a known route, or None if unknown."""
    route_id = _route_id(route)
    builder = _ROUTE_BUILDERS.get(route_id)
    if builder is None:
        return None
    return builder(data)


def get_builtin_route_html(route: str) -> Optional[str]:
    """Static template (no tool data) for ``resources/read`` / scaffolding."""
    return render_widget_html(route, None)


def build_widget_html_for_route(route: str) -> str:
    """HTML for scaffolding: known route template or generic JSON viewer."""
    return get_builtin_route_html(route) or build_generic_widget(_route_id(route))
